        vm.assume(caller != address(0));

        // Scenario: call SetMinSum with val1 (might revert if already initialized)
        // Then maybe try to initialize, then call SetMinSum with val2, then call Collect

        // Determine a valid order: call SetMinSum(val1) first (should succeed since not initialized)
        (bool success1,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val1));

        // Then initialize
        c.Initialized();

        // Then try SetMinSum(val2) - should revert because already initialized
        (bool success2,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val2));

        // Then fund the contract and caller for Collect
        vm.deal(caller, am);
        vm.deal(address(c), am);

        // Call Put to give caller some balance and set unlock time
        vm.prank(caller);
        c.Put{value: am}(lockTime);

        // Warp time to after unlock
