        // Now call Collect
        vm.prank(caller);
        (bool successCollect,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // The rule: MinSum must be val1 if SetMinSum(val1) succeeded, or 0 if it also failed
        uint256 expectedMinSum;
