pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 depositAmount, uint256 collectAmount) public {
        // Ensure non-zero deposit and collect amounts for meaningful test
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        vm.assume(_lockTime <= type(uint256).max / 2);
        vm.assume(_val <= type(uint256).max);
        vm.deal(address(this), depositAmount);

        // Step 1: Setup – SetMinSum must be called before Initialized
        c.SetMinSum(_val);
        // Verify that the value was stored correctly in reference
        assertTrue(c.MinSum() == _val, "MinSum set incorrectly");

        // Step 2: Initialize (after this, SetMinSum and SetLogFile revert)
        c.Initialized();

        // Step 3: Deposit some funds to create a holder balance
        uint256 depositBefore = address(c).balance;
        c.Put{value: depositAmount}(_lockTime);
        uint256 depositAfter = address(c).balance;
        // Ensure deposit went through
        assertTrue(depositAfter - depositBefore == depositAmount, "deposit not processed");

        // Step 4: Advance time beyond unlockTime so Collect can succeed
        uint256 curempt = c.Acc(address(this)).unlockTime;
        if (curempt > block.timestamp) {
            vm.warp(curempt + 1);
        }

        // Step 5: Call Collect with the collected amount
        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attempt Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Rule: If Collect succeeded, MinSum must equal the last value set (which is _val)
        if (success) {
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after successful Collect");
        } else {
            // If Collect reverted, MinSum should still be unchanged
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after reverted Collect");
        }
    }
}

